        <span className="text-sm text-slate-700">
          {t("workspace.settings.profile.account_created")}
        </span>
        <span className="text-sm font-medium text-slate-900">{formatDate(createdAt)}</span>
      </div>
      <div className="flex items-center justify-between">
        <span className="text-sm text-slate-700">
          {t("workspace.settings.profile.last_login")}
        </span>
        <span className="text-sm font-medium text-slate-900">{formatDate(lastLoginAt)}</span>
      </div>
    </div>
  );
};
"use client";

import { useTranslation } from "react-i18next";
import { TUserNotificationSettings } from "@formbricks/types/user";
import { Button } from "@/modules/ui/components/button";

interface DownloadMyDataProps {
  userName: string;
  userEmail: string;
  userLocale: string;
  notificationSettings: TUserNotificationSettings;
  organizationMemberships: { name: string; role: string }[];
}

export const DownloadMyData = ({
  userName,
  userEmail,
  userLocale,
  notificationSettings,
  organizationMemberships,
}: Readonly<DownloadMyDataProps>) => {
  const { t } = useTranslation();

  const handleDownload = () => {
    const data = {
      name: userName,
      email: userEmail,
      locale: userLocale,
      notificationSettings,
      organizationMemberships: organizationMemberships.map((org) => ({
        organizationName: org.name,
        role: org.role,
      })),
    };

    const jsonString = JSON.stringify(data, null, 2);
    const blob = new Blob([jsonString], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "formbricks-account-data.json";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div>
      <p className="text-sm text-slate-700">
        {t("workspace.settings.profile.download_my_data_description")}
      </p>
      <Button className="mt-4" variant="secondary" size="sm" onClick={handleDownload}>
        {t("workspace.settings.profile.download_my_data")}
      </Button>
    </div>
  );
};

import type { TSurveyDateElement, TSurveyElement } from "@formbricks/types/surveys/elements";
import { formatDateWithOrdinal } from "./datetime";

export type TSurveyDateFormatMap = Partial<Record<string, TSurveyDateElement["format"]>>;

const ISO_STORED_DATE_PATTERN = /^(\d{4})-(\d{1,2})-(\d{1,2})$/;

const buildDate = (year: number, month: number, day: number): Date | null => {
  if ([year, month, day].some((value) => Number.isNaN(value))) {
    return null;
  }

  const parsedDate = new Date(year, month - 1, day);

  if (
    parsedDate.getFullYear() !== year ||
    parsedDate.getMonth() !== month - 1 ||
    parsedDate.getDate() !== day
  ) {
    return null;
  }

  return parsedDate;
};

const parseLegacyStoredDateValue = (value: string, format: TSurveyDateElement["format"]): Date | null => {
  const parts = value.split("-");

  if (parts.length !== 3 || parts.some((part) => !/^\d{1,4}$/.test(part))) {
    return null;
  }

  const [first, second, third] = parts.map(Number);

  switch (format) {
    case "M-d-y":
      return buildDate(third, first, second);
    case "d-M-y":
      return buildDate(third, second, first);
    case "y-M-d":
      return buildDate(first, second, third);
  }
};

export const parseStoredDateValue = (value: string, format?: TSurveyDateElement["format"]): Date | null => {
  const isoMatch = ISO_STORED_DATE_PATTERN.exec(value);

  if (isoMatch) {
    return buildDate(Number(isoMatch[1]), Number(isoMatch[2]), Number(isoMatch[3]));
  }

  if (format) {
    return parseLegacyStoredDateValue(value, format);
  }

  if (/^\d{1,2}-\d{1,2}-\d{4}$/.test(value)) {
    return parseLegacyStoredDateValue(value, "d-M-y");
  }

  return null;
};

export const formatStoredDateForDisplay = (
  value: string,
  format: TSurveyDateElement["format"] | undefined,
  locale: string = "en-US"
): string | null => {
  const parsedDate = parseStoredDateValue(value, format);

  if (!parsedDate) {
    return null;
  }

  return formatDateWithOrdinal(parsedDate, locale);
};

export const getSurveyDateFormatMap = (elements: TSurveyElement[]): TSurveyDateFormatMap => {
  return elements.reduce<TSurveyDateFormatMap>((dateFormats, element) => {
    if (element.type === "date") {
      dateFormats[element.id] = element.format;
    }

    return dateFormats;
  }, {});
};

import { type Locale } from "date-fns";
import { de, enUS, es, fr, hu, ja, nl, pt, ptBR, ro, ru, sv, tr, zhCN, zhTW } from "date-fns/locale";

const DEFAULT_LOCALE = "en-US";

const DEFAULT_DATE_DISPLAY_OPTIONS: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "short",
  day: "numeric",
};

const DEFAULT_DATE_TIME_DISPLAY_OPTIONS: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "long",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit",
};

// Helper function to calculate difference in days between two dates
export const diffInDays = (date1: Date, date2: Date) => {
  const diffTime = Math.abs(date2.getTime() - date1.getTime());
  return Math.floor(diffTime / (1000 * 60 * 60 * 24));
};

export const formatDateForDisplay = (
  date: Date,
  locale: string = DEFAULT_LOCALE,
  options: Intl.DateTimeFormatOptions = DEFAULT_DATE_DISPLAY_OPTIONS
): string => {
  return new Intl.DateTimeFormat(locale, options).format(date);
};

export const formatDateTimeForDisplay = (
  date: Date,
  locale: string = DEFAULT_LOCALE,
  options: Intl.DateTimeFormatOptions = DEFAULT_DATE_TIME_DISPLAY_OPTIONS
): string => {
  return new Intl.DateTimeFormat(locale, options).format(date);
};

export const formatDateWithOrdinal = (date: Date, locale: string = DEFAULT_LOCALE): string => {
  return formatDateForDisplay(date, locale, {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

export const isValidDateString = (value: string) => {
  const regex = /^(?:\d{4}-\d{1,2}-\d{1,2}|\d{1,2}-\d{1,2}-\d{4})$/;

  if (!regex.test(value)) {
    return false;
  }

  const normalizedValue = /^\d{1,2}-\d{1,2}-\d{4}$/.test(value)
    ? value.replace(/(\d{1,2})-(\d{1,2})-(\d{4})/, "$3-$2-$1")
    : value;

  const date = new Date(normalizedValue);
  return !Number.isNaN(date.getTime());
};

export const getFormattedDateTimeString = (date: Date, timeZone: string = "UTC"): string => {
  const options: Intl.DateTimeFormatOptions = {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
    // Append the zone (e.g. "UTC", "GMT+8") so every exported/integrated Timestamp is
    // self-describing: rows written under different org settings stay distinguishable,
    // and downstream ETL never has to guess the zone.
    timeZoneName: "short",
    timeZone,
  };

  // An invalid IANA zone makes Intl.DateTimeFormat throw a RangeError. Degrade to UTC
  // rather than failing the entire export or integration delivery.
  try {
    return new Intl.DateTimeFormat("en-CA", options).format(date).replace(",", "");
  } catch {
    return new Intl.DateTimeFormat("en-CA", { ...options, timeZone: "UTC" }).format(date).replace(",", "");
  }
};

/**
 * Maps an app locale code to the date-fns locale the calendar needs for month names, weekday headers
 * and the first day of the week.
 *
 * `Intl` (which the formatters above use) takes the BCP 47 tag directly, but `react-day-picker` wants a
 * date-fns `Locale` object, so the app's locale codes have to be mapped explicitly. The keys mirror
 * `apps/web/locales/*.json`; anything else — including a survey language code that never became an app
 * locale — falls back to en-US rather than throwing.
 */
export const getDateFnsLocale = (localeCode?: string): Locale => {
  if (!localeCode) return enUS;

  const normalized = localeCode.toLowerCase();

  // Script-and-region-specific tags first: these do not survive being cut down to a base language
  // (pt-BR and pt-PT differ, and zh-Hans/zh-Hant are different scripts, not different regions).
  if (normalized.startsWith("pt-br")) return ptBR;
  if (normalized.startsWith("pt-pt")) return pt;
  if (normalized.startsWith("zh-hans") || normalized === "zh-cn") return zhCN;
  if (normalized.startsWith("zh-hant") || normalized === "zh-tw" || normalized === "zh-hk") return zhTW;

  const localeMap: Record<string, Locale> = {
    de,
    en: enUS,
    es,
    fr,
    hu,
    ja,
    nl,
    pt: ptBR, // Bare "pt" is ambiguous; Brazilian is the larger audience and matches the survey packages.
    ro,
    ru,
    sv,
    tr,
    zh: zhCN,
  };

  return localeMap[normalized.split("-")[0]] ?? enUS;
};

/**
 * Serialises a local calendar day as `yyyy-MM-dd`.
 *
 * Machine-facing on purpose — this is the value chart and dashboard time filters hand to Cube — so it
 * stays non-localized. Deliberately not `toISOString().slice(0, 10)`: that converts to UTC first, so
 * a user east of UTC would emit tomorrow's date and one west of it yesterday's.
 */
export const formatLocalDay = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
};

/**
 * Parses a `yyyy-MM-dd` day back to local midnight — the inverse of `formatLocalDay`.
 *
 * `new Date("2026-08-05")` parses as UTC midnight, which displays (and re-emits) a day earlier for
 * anyone west of UTC, so the value is rebuilt from its parts to keep the round trip symmetric.
 */
export const parseLocalDay = (value: string): Date => {
  const [year, month, day] = value.split("-").map(Number);

  return new Date(year, month - 1, day);
};

/**
 * Parses a stored date value — a bare `yyyy-MM-dd` or a full ISO timestamp — to the local midnight of
 * the calendar day it names, or `null` when it names none.
 *
 * The time part is dropped before parsing rather than handed to `Date`: a stored
 * `2026-08-05T00:00:00.000Z` is the 5th as written, and reading it as an instant would select the 4th
 * for any viewer west of UTC. Round-tripping through `formatLocalDay` accepts exactly the values an
 * `<input type="date">` did, so a value that predates the picker still renders, a rolled-over one
 * (`2026-13-45`) is refused rather than silently shown as a different day, and an unparseable one
 * yields `null` instead of the Invalid Date that would break the calendar.
 *
 * Only the day is validated, so a well-formed day followed by a malformed time still resolves to that
 * day. That is deliberate: the day is the part a date picker shows, these values can arrive from the
 * Management API rather than only from this UI, and the `<input type="date">` this replaced split on
 * `T` the same way — blanking a readable day over a broken time suffix would lose information.
 */
export const parseStoredDay = (value: string | null | undefined): Date | null => {
  if (!value) return null;

  const day = value.split("T")[0];
  const parsed = parseLocalDay(day);

  return formatLocalDay(parsed) === day ? parsed : null;
};

import { type Locale, formatDistance } from "date-fns";
import { de, enUS, es, fr, hu, ja, nl, pt, ptBR, ro, ru, sv, tr, zhCN, zhTW } from "date-fns/locale";
import { TUserLocale } from "@formbricks/types/user";
import { formatDateForDisplay } from "./utils/datetime";

const DEFAULT_LOCALE: TUserLocale = "en-US";
const TIME_SINCE_LOCALES: Record<TUserLocale, Locale> = {
  "de-DE": de,
  "en-US": enUS,
  "es-ES": es,
  "fr-FR": fr,
  "hu-HU": hu,
  "ja-JP": ja,
  "nl-NL": nl,
  "pt-BR": ptBR,
  "pt-PT": pt,
  "ro-RO": ro,
  "ru-RU": ru,
  "sv-SE": sv,
  "tr-TR": tr,
  "zh-Hans-CN": zhCN,
  "zh-Hant-TW": zhTW,
};

const isUserLocale = (locale: string): locale is TUserLocale => Object.hasOwn(TIME_SINCE_LOCALES, locale);

/** Maps locale strings to date-fns locales and falls back to English for unsupported inputs. */
const getLocaleForTimeSince = (locale: string): Locale =>
  isUserLocale(locale) ? TIME_SINCE_LOCALES[locale] : enUS;

export const timeSince = (dateString: string, locale: string = DEFAULT_LOCALE) => {
  const date = new Date(dateString);
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

export const timeSinceDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDistance(date, new Date(), {
    addSuffix: true,
    locale: getLocaleForTimeSince(locale),
  });
};

export const formatDate = (date: Date, locale: string = DEFAULT_LOCALE) => {
  return formatDateForDisplay(date, locale, {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

export const getTodaysDateTimeFormatted = (seperator: string) => {
  const date = new Date();
  const formattedDate = date.toISOString().split("T")[0].split("-").join(seperator);
  const formattedTime = date.toTimeString().split(" ")[0].split(":").join(seperator);

  return [formattedDate, formattedTime].join(seperator);
};

export const convertDatesInObject = <T>(obj: T, keysToIgnore?: Set<string>): T => {
  if (obj === null || typeof obj !== "object") {
    return obj; // Return if obj is not an object
  }
  if (Array.isArray(obj)) {
    // Handle arrays by mapping each element through the function
    return obj.map((item) => convertDatesInObject(item, keysToIgnore)) as unknown as T;
  }
  const newObj: Record<string, unknown> = {};
  for (const key in obj) {
    if (keysToIgnore?.has(key)) {
      newObj[key] = obj[key];
      continue;
    }
    if (
      (key === "createdAt" || key === "updatedAt") &&
      typeof obj[key] === "string" &&
      !isNaN(Date.parse(obj[key] as unknown as string))
    ) {
      newObj[key] = new Date(obj[key] as unknown as string);
    } else if (typeof obj[key] === "object" && obj[key] !== null) {
      newObj[key] = convertDatesInObject(obj[key], keysToIgnore);
    } else {
      newObj[key] = obj[key];
    }
  }
  return newObj as T;
};

